    -H 'Content-Type: application/json' \
    -H 'api-key: api_key' \
    -H 'sensorsdata-project: default' \
    -d '{
    "project_id": 1,
    "table": {
      "db_name": "test_db",
      "name": "test_table",
      "type": "TABLE",
      "engine": "MUTABLE",
      "primary_keys": ["id"],
      "columns": [
